fn update(scene: &mut GameScene<'_>, _time: &FrameTime) {
    // Touching the goal clears the level once.
    if scene.counter_value("cleared") == 0
        && scene.touching("Goal").iter().any(|name| name == "Player")
    {
        scene.set_counter("cleared", 1);
        scene.set_hud("Help", |hud| hud.text = "Level complete!".into());
    }
}
